-- Age-graded lessons for Seeds (3.5–6), Sprouts (7–10) and Blooms (11–15). Safe to run again.
insert into public.docs(path,data) values
  ('lessons/ex-s4', '{"body": "Pip is visiting the farm and the zoo! Can you make each animal''s sound?\n\nSay the animal''s name, then make its sound. Moo like a cow, quack like a duck, roar like a lion!", "courseId": "ex-seeds", "kind": "song", "mediaUrl": "", "minutes": 10, "order": 4, "title": "Animal friends", "vocab": "cow = a farm animal that says moo\nduck = a bird that says quack\nlion = a big cat that roars\nmonkey = an animal that swings in trees\nelephant = a very big animal with a long trunk", "level": "Seeds", "sample": true, "createdAt": 1793000000000}'::jsonb),
  ('lessons/ex-s5', '{"body": "Bloom says: touch your head! Touch your nose! Clap your hands! Blink your eyes!\n\nPlay with a grown-up. They say a body part, you touch it and say the word.", "courseId": "ex-seeds", "kind": "song", "mediaUrl": "", "minutes": 10, "order": 5, "title": "Touch your nose!", "vocab": "head = the top part of your body\nhand = you wave and clap with it\nnose = you smell with it\neyes = you see with them", "level": "Seeds", "sample": true, "createdAt": 1793000000001}'::jsonb),
  ('lessons/ex-s6', '{"body": "Pip lives in the garden with Mother, Father, Baby and Grandma. Grandma tells the best stories!\n\nPoint to a photo of your family and say who each person is.", "courseId": "ex-seeds", "kind": "story", "mediaUrl": "", "minutes": 10, "order": 6, "title": "Pip''s family", "vocab": "mother = your mum\nfather = your dad\nbaby = a very little child\ngrandma = your mum''s or dad''s mother", "level": "Seeds", "sample": true, "createdAt": 1793000000002}'::jsonb),
  ('lessons/ex-s7', '{"body": "The sun is a circle. A window can be a square. A slice of pizza is a triangle!\n\nFind one circle, one square and one triangle at home. Point and say the shape.", "courseId": "ex-seeds", "kind": "game", "mediaUrl": "", "minutes": 15, "order": 7, "title": "Shapes all around", "vocab": "circle = a round shape\nsquare = a shape with four equal sides\ntriangle = a shape with three sides\nstar = a shape with five points", "level": "Seeds", "sample": true, "createdAt": 1793000000003}'::jsonb),
  ('lessons/ex-s8', '{"body": "Buzz is hungry! What does Buzz want? A mango? Some bread? A glass of water?\n\nAt lunch, name the food on your plate in English.", "courseId": "ex-seeds", "kind": "game", "mediaUrl": "", "minutes": 10, "order": 8, "title": "Yummy food", "vocab": "mango = a sweet yellow fruit\nbread = food made from flour\nwater = what you drink when you are thirsty\nmilk = a white drink from cows", "level": "Seeds", "sample": true, "createdAt": 1793000000004}'::jsonb),
  ('lessons/ex-p3', '{"body": "Buzz was excited about the race. Drizzle was worried it might rain. When Buzz won, everyone was proud, and nobody was angry. Pip was surprised by the big cake!\n\nSay three sentences: \"I feel … when …\". Example: \"I feel proud when I finish my homework.\"", "courseId": "ex-sprouts", "kind": "speak", "mediaUrl": "", "minutes": 15, "order": 3, "title": "How do you feel?", "vocab": "excited = very happy about something that will happen\nworried = thinking something bad might happen\nproud = happy about something you did well\nangry = very cross\nsurprised = feeling something you did not expect", "level": "Sprouts", "sample": true, "createdAt": 1793000000005}'::jsonb),
  ('lessons/ex-p4', '{"body": "Drizzle read the forecast: \"Cloudy in the morning, a cool breeze at lunch, and a stormy evening with thunder.\" Pip packed an umbrella.\n\nLook outside and write a weather report for today in two sentences.", "courseId": "ex-sprouts", "kind": "story", "mediaUrl": "", "minutes": 20, "order": 4, "title": "Weather watch", "vocab": "cloudy = when clouds cover the sky\nbreeze = a soft, gentle wind\nstormy = with strong wind and rain\nthunder = the loud sound in a storm\nforecast = what the weather will be like later", "level": "Sprouts", "sample": true, "createdAt": 1793000000006}'::jsonb),
  ('lessons/ex-p5', '{"body": "A rock is heavy, a feather is light. The early bird gets up at 5 o''clock, the late bird at 10! A lion is loud, a mouse is quiet.\n\nWrite the opposite of each word: heavy, early, quiet, hot, happy.", "courseId": "ex-sprouts", "kind": "game", "mediaUrl": "", "minutes": 15, "order": 5, "title": "Opposites race", "vocab": "heavy = hard to lift\nlight = easy to lift, not heavy\nearly = before the usual time\nlate = after the usual time\nquiet = making very little sound", "level": "Sprouts", "sample": true, "createdAt": 1793000000007}'::jsonb),
  ('lessons/ex-p6', '{"body": "Pip went to the market with a basket and some coins. The vendor said the mangoes were ₹60. Pip tried to bargain: \"₹50, please?\" The vendor smiled and gave Pip a receipt.\n\nAct it out with a grown-up: one of you is the vendor, one is the buyer.", "courseId": "ex-sprouts", "kind": "story", "mediaUrl": "", "minutes": 20, "order": 6, "title": "At the market", "vocab": "vendor = a person who sells things\nbasket = a bag made of woven sticks\ncoins = round pieces of money\nbargain = to ask for a lower price\nreceipt = a paper that shows what you paid", "level": "Sprouts", "sample": true, "createdAt": 1793000000008}'::jsonb),
  ('lessons/ex-p7', '{"body": "Yesterday Buzz ran to the pond, swam with the fish, ate a sandwich, wrote a letter and caught a ball!\n\nTell a grown-up five things you did yesterday. Use words like ran, ate and wrote.", "courseId": "ex-sprouts", "kind": "game", "mediaUrl": "", "minutes": 15, "order": 7, "title": "Yesterday''s adventure", "vocab": "ran = the past of run\nswam = the past of swim\nate = the past of eat\nwrote = the past of write\ncaught = the past of catch", "level": "Sprouts", "sample": true, "createdAt": 1793000000009}'::jsonb),
  ('lessons/ex-b3', '{"body": "A strong argument has a clear claim, a credible reason and an example. Know your audience, emphasise your best point, and conclude by repeating your claim.\n\nRecord a 90-second talk: \"Schools should start at 9 a.m.\" Convince a listener who disagrees.", "courseId": "ex-blooms", "kind": "speak", "mediaUrl": "", "minutes": 25, "order": 3, "title": "Persuade like a pro", "vocab": "argument = a reason or set of reasons for an idea\nconvince = to make someone believe something\naudience = the people listening or watching\ncredible = easy to believe and trust\nemphasise = to show something is important\nconclude = to end, or to decide after thinking", "level": "Blooms", "sample": true, "createdAt": 1793000000010}'::jsonb),
  ('lessons/ex-b4', '{"body": "A good reporter writes a short headline, checks every fact with a second source, and keeps bias out of the story.\n\nWrite a 100-word news report about something that happened at your school this week. Verify one fact, then summarise the story in one sentence.", "courseId": "ex-blooms", "kind": "story", "mediaUrl": "", "minutes": 25, "order": 4, "title": "Be a news reporter", "vocab": "headline = the title of a news story\nfact = something that is true and can be checked\nsource = where information comes from\nverify = to check that something is true\nbias = favouring one side unfairly\nsummarise = to give the main points in a few words", "level": "Blooms", "sample": true, "createdAt": 1793000000011}'::jsonb),
  ('lessons/ex-b5', '{"body": "Formal emails are polite and clear. Start with \"Dear Ms Rao,\", say why you are writing (\"I am writing regarding…\"), make your request, mention any deadline, and end with \"Yours sincerely\".\n\nWrite a formal email to your teacher asking for one extra day for a project. Say what you will attach.", "courseId": "ex-blooms", "kind": "game", "mediaUrl": "", "minutes": 25, "order": 5, "title": "Write a formal email", "vocab": "formal = polite and serious, for school or work\nrequest = to ask for something politely\nregarding = about\nattach = to add a file to an email\ndeadline = the last day to finish something\nsincerely = used to end a formal letter", "level": "Blooms", "sample": true, "createdAt": 1793000000012}'::jsonb),
  ('lessons/ex-b6', '{"body": "Idioms say one thing but mean another. The test was a piece of cake. A joke can break the ice. I''m under the weather today. I eat pizza once in a blue moon. Exams are coming, time to hit the books!\n\nUse three idioms in a short story about your week, then say it aloud.", "courseId": "ex-blooms", "kind": "speak", "mediaUrl": "", "minutes": 20, "order": 6, "title": "Idioms that bloom", "vocab": "piece of cake = very easy\nbreak the ice = to help people start talking\nunder the weather = feeling a little ill\nonce in a blue moon = very rarely\nhit the books = to study hard", "level": "Blooms", "sample": true, "createdAt": 1793000000013}'::jsonb),
  ('lessons/ex-b7', '{"body": "Our climate is changing. Pollution from cars and factories has a big impact, and one consequence is hotter summers. Renewable energy, like sun and wind, can help, and so can choices we make to conserve water and power.\n\nWrite a speech of 150 words: three things your family can do this month to help the planet. Give a reason for each.", "courseId": "ex-blooms", "kind": "story", "mediaUrl": "", "minutes": 25, "order": 7, "title": "Big ideas: our planet", "vocab": "climate = the usual weather of a place over many years\npollution = dirty or harmful things in air, water or land\nimpact = a strong effect\nconsequence = a result of an action\nrenewable = can be used again and never runs out\nconserve = to use carefully so it lasts", "level": "Blooms", "sample": true, "createdAt": 1793000000014}'::jsonb)
on conflict (path) do nothing;

-- English meanings for the original sample lessons (skipped if a trainer has changed them)
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('confident = sure that you can do something
opinion = what you think about something
because = gives the reason
example = something that shows what you mean'::text)) where path='lessons/ex-b1' and data->>'vocab'='confident = आत्मविश्वासी
opinion = राय
because = क्योंकि
example = उदाहरण';
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('agree = to think the same as someone
disagree = to think differently from someone
reason = why something is true or happens
however = but; used to add a different idea'::text)) where path='lessons/ex-b2' and data->>'vocab'='agree = सहमत
disagree = असहमत
reason = कारण
however = फिर भी';
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('puddle = a small pool of rainwater
jump = to push off the ground with your legs
splash = water flying up when something hits it
careful = paying attention so nothing goes wrong'::text)) where path='lessons/ex-p1' and data->>'vocab'='puddle = पानी का गड्ढा
jump = कूदना
splash = छपाका
careful = सावधान';
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('jumps = is jumping (he jumps)
flies = is moving through the air (a bird flies)
reads = is looking at words (she reads)
sings = is making music with the voice'::text)) where path='lessons/ex-p2' and data->>'vocab'='jumps = कूदता है
flies = उड़ता है
reads = पढ़ता है
sings = गाता है';
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('hello = what you say when you meet someone
goodbye = what you say when you leave
thank you = what you say when someone helps you
please = the magic word when you ask'::text)) where path='lessons/ex-s1' and data->>'vocab'='hello = नमस्ते
goodbye = अलविदा
thank you = धन्यवाद
please = कृपया';
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('red = the colour of a tomato
green = the colour of grass and Pip
yellow = the colour of the sun
blue = the colour of the sky
pink = the colour of Bloom'::text)) where path='lessons/ex-s2' and data->>'vocab'='red = लाल
green = हरा
yellow = पीला
blue = नीला
pink = गुलाबी';
update public.docs set data = jsonb_set(data,'{vocab}',to_jsonb('one = 1
two = 2
three = 3
four = 4
five = 5'::text)) where path='lessons/ex-s3' and data->>'vocab'='one = एक
two = दो
three = तीन
four = चार
five = पाँच';
